// Generates every platform's theme from one source: replica/design/tokens.json
//   node scripts/build-tokens.mjs
// Writes:
//   replica/design/tokens.css          CSS custom properties (admin dashboard, web previews)
//   replica/design/tailwind.preset.cjs Tailwind theme mapped to those properties (admin dashboard)
//   packages/shared/src/theme.ts       typed theme object for the Expo apps (rider, driver)
// Never edit the generated files by hand: change tokens.json and run this again.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'replica/design/tokens.json'), 'utf8'));
const banner = 'Generated by scripts/build-tokens.mjs from replica/design/tokens.json. Do not edit.';

function write(rel, text) {
  const path = join(root, rel);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
  console.log('wrote', rel);
}

// ---------- CSS
const css = [];
css.push(`/* ${banner} */`, ':root {');
for (const [k, v] of Object.entries(tokens.color)) css.push(`  --color-${k}: ${v};`);
css.push(`  --font-sans: ${tokens.font.sans};`);
for (const [k, t] of Object.entries(tokens.type)) {
  css.push(`  --text-${k}-size: ${t.size}px;`, `  --text-${k}-line: ${t.line}px;`, `  --text-${k}-weight: ${t.weight};`);
}
tokens.space.forEach((v, i) => css.push(`  --space-${i}: ${v}px;`));
for (const [k, v] of Object.entries(tokens.radius)) css.push(`  --radius-${k}: ${v}px;`);
for (const [k, v] of Object.entries(tokens.shadow)) css.push(`  --shadow-${k}: ${v};`);
for (const [k, v] of Object.entries(tokens.motion)) css.push(`  --motion-${k}: ${v};`);
for (const [k, v] of Object.entries(tokens.size)) css.push(`  --size-${k}: ${v}px;`);
for (const [k, v] of Object.entries(tokens.layout)) css.push(`  --layout-${k}: ${v}px;`);
css.push('}', '');
write('replica/design/tokens.css', css.join('\n'));

// ---------- Tailwind preset
const colors = Object.fromEntries(Object.keys(tokens.color).map(k => [k, `var(--color-${k})`]));
const fontSize = Object.fromEntries(Object.entries(tokens.type).map(([k, t]) =>
  [k, [`${t.size}px`, { lineHeight: `${t.line}px`, fontWeight: String(t.weight) }]]));
const spacing = Object.fromEntries(tokens.space.map((v, i) => [String(i), `${v}px`]));
const borderRadius = Object.fromEntries(Object.entries(tokens.radius).map(([k, v]) => [k, `${v}px`]));
const boxShadow = Object.fromEntries(Object.keys(tokens.shadow).map(k => [k, `var(--shadow-${k})`]));
const preset = {
  theme: {
    colors: { transparent: 'transparent', current: 'currentColor', ...colors },
    fontFamily: { sans: tokens.font.sans.split(',').map(s => s.trim()) },
    fontSize, spacing, borderRadius, boxShadow,
    extend: { minHeight: { touch: `${tokens.size['touch-min']}px` }, minWidth: { touch: `${tokens.size['touch-min']}px` } },
  },
};
write('replica/design/tailwind.preset.cjs', `// ${banner}\nmodule.exports = ${JSON.stringify(preset, null, 2)};\n`);

// ---------- React Native theme
const rnType = Object.fromEntries(Object.entries(tokens.type).map(([k, t]) => [k, {
  fontSize: t.size, lineHeight: t.line,
  fontFamily: t.weight >= 700 ? 'AtkinsonHyperlegible_700Bold' : 'AtkinsonHyperlegible_400Regular',
}]));
const theme = {
  color: tokens.color,
  type: rnType,
  space: tokens.space,
  radius: tokens.radius,
  size: tokens.size,
  layout: tokens.layout,
  motion: { fast: parseInt(tokens.motion.fast, 10), base: parseInt(tokens.motion.base, 10) },
};
write('packages/shared/src/theme.ts',
  `// ${banner}\nexport const theme = ${JSON.stringify(theme, null, 2)} as const;\n\n` +
  `export type ColorRole = keyof typeof theme.color;\nexport type TypeRole = keyof typeof theme.type;\n`);
